<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageRef;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageAttributes;
use Civi\Lughauth\Features\Notification\Message\Domain\Message;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageFilter;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageCursor;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageReadGateway;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageSlide;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class MessageVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly MessageReadGateway $readGateway,
        private readonly MessageWriteGateway $writeGateway,
        private readonly TenantVisibilityService $tenantVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(Message $content): MessageAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(Message $content): MessageAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(MessageAttributes $attributes, ?Message $original = null): MessageAttributes
    {
        $this->logDebug("Copy with fixed for Message");
        $span = $this->startSpan("Copy with fixed for  Message");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new MessagePresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(MessageAttributes $attributes, ?Message $original = null): MessageAttributes
    {
        $this->logDebug("Copy with hidden for Message");
        $span = $this->startSpan("Copy with hidden for  Message");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|MessageRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Message");
        $span = $this->startSpan("Check visibility of an iterator for  Message");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new MessageRef($value));
            } elseif ($value instanceof MessageRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new MessageFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(MessageFilter $filter, ?MessageCursor $cursor = null): MessageSlide
    {
        $this->logDebug("List visibles for Message");
        $span = $this->startSpan("List visibles for  Message");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (Message $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(MessageFilter $filter): int
    {
        $this->logDebug("Count visibles for Message");
        $span = $this->startSpan("Count visibles for  Message");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(MessageFilter $filter, ?MessageCursor $cursor = null): MessageSlide
    {
        $this->logDebug("List visibles for update for Message");
        $span = $this->startSpan("List visibles for update for  Message");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (Message $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(MessageFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Message");
        $span = $this->startSpan("Count visibles for update for  Message");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(MessageRef $ref): ?Message
    {
        $this->logDebug("Retrieve visible for Message");
        $span = $this->startSpan("Retrieve visible for  Message");
        try {
            $filter = new MessageFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(MessageRef $ref): ?Message
    {
        $this->logDebug("Retrieve visible for update for Message");
        $span = $this->startSpan("Retrieve visible for update for  Message");
        try {
            $filter = new MessageFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?MessageRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Message");
        $span = $this->startSpan("Check fields for fix for Message");
        try {
            $result = $this->dispatcher->dispatch(new MessageCollectNonEditableFields(Message::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?MessageRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Message");
        $span = $this->startSpan("Check fields to hide for  Message");
        try {
            $result = $this->dispatcher->dispatch(new MessageCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(MessageAttributes $attributes): MessageAttributes
    {
        $this->logDebug("Check visibility of parent references for Message");
        $span = $this->startSpan("Check visibility of parent references for  Message");
        try {
            $tenant = $attributes->getTenant();
            if (null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant)) {
                throw new NotFoundException("Unknown Tenant " . ($tenant->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(MessageFilter $filter): MessageFilter
    {
        $this->logDebug("Compose visibility filter for Message");
        $span = $this->startSpan("Compose visibility filter for  Message");
        try {
            $result = $this->dispatcher->dispatch(new MessageRestrictFilterToVisibility($filter));
            return $result->messageFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(Message $value): bool
    {
        $this->logDebug("Check if item is visible for Message");
        $span = $this->startSpan("Check if item is visible for  Message");
        try {
            $result = $this->dispatcher->dispatch(new MessageVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(Message $content, bool $inlist): MessageAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Message");
        $span = $this->startSpan("Prepare hydration to visible data for Message");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new MessageEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
